import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Warum verhält sich die Admin-Oberfläche des Adapters falsch?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/04.fehlerbehebung/04.admin-oberflaeche.md"},"headers":[],"relativePath":"de/adapter/esphome/fehlerbehebung/admin-oberflaeche.md","filePath":"de/adapter/esphome/fehlerbehebung/admin-oberflaeche.md","lastUpdated":null}'),i={name:"de/adapter/esphome/fehlerbehebung/admin-oberflaeche.md"};function d(s,e,o,h,u,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="warum-verhalt-sich-die-admin-oberflache-des-adapters-falsch" tabindex="-1">Warum verhält sich die Admin-Oberfläche des Adapters falsch? <a class="header-anchor" href="#warum-verhalt-sich-die-admin-oberflache-des-adapters-falsch" aria-label="Permalink to &quot;Warum verhält sich die Admin-Oberfläche des Adapters falsch?&quot;">​</a></h1><p><a id="warning-esphome-has-invalid-jsonconfig"></a></p><h2 id="was-bedeutet-die-warnung-esphome-has-an-invalid-jsonconfig" tabindex="-1">Was bedeutet die Warnung &quot;esphome has an invalid jsonConfig&quot;? <a class="header-anchor" href="#was-bedeutet-die-warnung-esphome-has-an-invalid-jsonconfig" aria-label="Permalink to &quot;Was bedeutet die Warnung &quot;esphome has an invalid jsonConfig&quot;?&quot;">​</a></h2><p>Die Warnung ist harmlos, du musst nichts tun. Sie kommt vom Admin, der die Beschreibung der Einstellungsseite prüft, nicht vom laufenden Adapter. Einstellungen werden trotzdem gespeichert, Geräte und Dashboard arbeiten normal.</p><p>Hinter <code>esphome has an invalid jsonConfig:</code> steht das Feld, das der Admin beanstandet (<code>instancePath</code>). Meist kennt der Admin nur eine Feldangabe nicht, etwa die freie Eingabe neben einer Auswahlliste bei „ESPHome Dashboard-Version“, der Dashboard-Adresse oder „Python-Version“.</p><p>Der Adapter braucht Admin 7.8.20 oder neuer. Mit einem älteren Admin stellt er die Seite nicht richtig dar, dann aktualisiere zuerst den Admin. Startet gleichzeitig das Dashboard nicht, liegt das nicht an dieser Warnung: <a href="./dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Dashboard startet nicht</a>.</p><p><strong>Siehe auch:</strong> <a href="#save-buttons-active-layout-unusable">Speichern-Buttons aktiv oder Layout unbrauchbar</a> · <a href="./../erste-schritte/installation#instance-stay-red-after-install">Instanz bleibt nach Installation oder Update rot</a></p><p><a id="save-buttons-active-layout-unusable"></a></p><h2 id="warum-sind-speichern-buttons-aktiv-oder-das-layout-auf-dem-handy-unbrauchbar" tabindex="-1">Warum sind Speichern-Buttons aktiv oder das Layout auf dem Handy unbrauchbar? <a class="header-anchor" href="#warum-sind-speichern-buttons-aktiv-oder-das-layout-auf-dem-handy-unbrauchbar" aria-label="Permalink to &quot;Warum sind Speichern-Buttons aktiv oder das Layout auf dem Handy unbrauchbar?&quot;">​</a></h2><p>Die Einstellungsseite braucht Admin 7.8.20 oder neuer. Mit älteren Versionen fehlen Teile, z. B. die Geräteverwaltung im Reiter „Geräte“. Aktualisiere den Admin-Adapter und lade die Seite neu.</p><p>Die Geräte stehen als Karten im Reiter „Geräte“ und werden dort ohne „Speichern“ hinzugefügt, geändert und gelöscht. „Speichern“ brauchst du nur für die anderen Reiter.</p>',11)])])}const b=a(i,[["render",d]]);export{m as __pageData,b as default};
